import{_ as a}from"./chunks/overview-hero.D7m_mGxJ.js";import{_ as r,o as t,c as o,a3 as n}from"./chunks/framework.D1iekJsc.js";const m=JSON.parse('{"title":"Welcome","description":"MiniTavern Ultra handbook — one-sentence character cards and v2/v3 import, GPT, Claude, OpenRouter or local models, lorebooks, regex, presets, vision and picture replies, backups and chat archives.","frontmatter":{"title":"Welcome","description":"MiniTavern Ultra handbook — one-sentence character cards and v2/v3 import, GPT, Claude, OpenRouter or local models, lorebooks, regex, presets, vision and picture replies, backups and chat archives.","head":[["meta",{"name":"keywords","content":"tavern,AI tavern,MiniTavern,AI companion,AI friend,AI local chat,Silly Tavern,SillyTavern,Silly Tavern mobile,Silly Tavern Android,Silly Tavern iOS,AI roleplay,character card,AI chat,mobile AI,offline AI,AI story,local LLM,Ollama,LM Studio,lorebook,regex,BYOK,user guide,docs,AI chat client"}],["meta",{"property":"og:title","content":"Welcome · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern Ultra handbook — one-sentence character cards and v2/v3 import, GPT, Claude, OpenRouter or local models, lorebooks, regex, presets, vision and picture replies, backups and chat archives."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/en"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/en"}]]},"headers":[],"relativePath":"en/index.md","filePath":"en/index.md","lastUpdated":1792058564000}'),l={name:"en/index.md"};function i(s,e,d,c,u,h){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="welcome" tabindex="-1">Welcome <a class="header-anchor" href="#welcome" aria-label="Permalink to &quot;Welcome&quot;">​</a></h1><div class="overview-hero"><p><img src="'+a+'" alt="MiniTavern Ultra app screens"></p></div><h2 id="about-the-app" tabindex="-1">About the app <a class="header-anchor" href="#about-the-app" aria-label="Permalink to &quot;About the app&quot;">​</a></h2><p><strong>MiniTavern Ultra</strong> is an <strong>AI roleplay chat</strong> app.</p><p><strong>Create a companion. Play your story.</strong> — one sentence builds a card, or bring in a v2 / v3 card.</p><p>Connect GPT, Claude, OpenRouter, or a local model at home. Keys stay on the phone, and chats stay on the device first.</p><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What you can do&quot;">​</a></h2><ol><li><p><strong>One sentence, or a v2 / v3 card</strong><br> Describe who you want. Preview the name, persona, and greeting, then chat. See <a href="/ultra_guides/en/manual/ai-create">Create with AI</a>. PNG / JSON follow mainstream character card v2 and v3 — <a href="/ultra_guides/en/manual/chara-card">Character cards</a>.</p></li><li><p><strong>GPT, Claude, OpenRouter, or local</strong><br> Bring your own key, or connect Ollama / LM Studio. Keys stay in on-device secure storage. See <a href="/ultra_guides/en/manual/model-link">Model link</a>. Free tiers: <a href="/ultra_guides/en/free-cloud/">Free cloud APIs</a>. On your PC: <a href="/ultra_guides/en/local/">Run local models</a>.</p></li><li><p><strong>Lorebook, regex, presets — create or import</strong><br><a href="/ultra_guides/en/manual/lorebook">Lorebook</a> holds the setting, <a href="/ultra_guides/en/manual/regex">regex</a> shapes what you see, <a href="/ultra_guides/en/manual/presets">presets</a> swap a whole prompt layout. Write them, or import files you already have. Sampling stays in model settings.</p></li><li><p><strong>Immersive chat: see, recognize, reply with pictures</strong><br> Photos you send can be read, and the people in them recognized. Characters can reply with a picture that follows the scene. See <a href="/ultra_guides/en/manual/chat">Chat</a>.</p></li><li><p><strong>Backup and chat archives</strong><br> A <a href="/ultra_guides/en/manual/backup">full backup</a> moves characters, chats, lorebooks, and regex — you choose whether keys are included. A <a href="/ultra_guides/en/manual/chat-archive">chat archive</a> can merge into an old thread or open as a new one.</p></li></ol><h2 id="why-minitavern" tabindex="-1">Why MiniTavern <a class="header-anchor" href="#why-minitavern" aria-label="Permalink to &quot;Why MiniTavern&quot;">​</a></h2><ul><li><strong>Cards are fast</strong>: one sentence, or import v2 / v3</li><li><strong>Your model</strong>: GPT, Claude, OpenRouter, or local — keys stay on device</li><li><strong>Long-arc tools</strong>: lorebook, regex, presets, and persona — create or import</li><li><strong>The chat can see</strong>: photos, people, and picture replies</li><li><strong>Each chat, its own setup</strong>: model, preset, lorebook, regex, and image gen</li><li><strong>Take it with you</strong>: full backup and per-chat archives</li></ul><h2 id="quick-start" tabindex="-1">Quick start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick start&quot;">​</a></h2><ol><li><strong>Configure a model</strong>: Settings → <a href="/ultra_guides/en/manual/model-link">Model link</a> → New, Test, set as default.</li><li><strong>Import or create a character</strong>: Characters → <a href="/ultra_guides/en/manual/chara-card">Import or create</a>.</li><li><strong>Start chatting</strong>: open a chat from the character — companion mode or in-character play, your choice.</li></ol><p>More detail: <a href="/ultra_guides/en/manual/getting-started">Getting started</a>. Local deploy: <a href="/ultra_guides/en/local/">overview</a> · <a href="/ultra_guides/en/quickstart">language-model quickstart</a> · <a href="/ultra_guides/en/local/image-gen/">image gen</a>. Free quotas: <a href="/ultra_guides/en/free-cloud/">Free cloud APIs</a>.</p><h2 id="handbook-entry-points" tabindex="-1">Handbook entry points <a class="header-anchor" href="#handbook-entry-points" aria-label="Permalink to &quot;Handbook entry points&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Section</th><th>Description</th></tr></thead><tbody><tr><td><a href="/ultra_guides/en/manual/">Manual home</a></td><td>Suggested reading order and overview</td></tr><tr><td><a href="/ultra_guides/en/manual/model-link">Models</a></td><td>Links, parameters, Test, and troubleshooting</td></tr><tr><td><a href="/ultra_guides/en/free-cloud/">Free cloud APIs</a></td><td>Vendor free tiers and how to fill Keys</td></tr><tr><td><a href="/ultra_guides/en/local/">Run local models</a></td><td>Local language / image deploy</td></tr><tr><td><a href="/ultra_guides/en/manual/chara-card">Characters</a> · <a href="/ultra_guides/en/manual/ai-create">Create with AI</a></td><td>Import, edit, start chats, generate from a description</td></tr><tr><td><a href="/ultra_guides/en/manual/chat">Chat</a> · <a href="/ultra_guides/en/manual/bubbles">Bubbles and input</a></td><td>Conversation, appearance, session settings</td></tr><tr><td><a href="/ultra_guides/en/manual/lorebook">Advanced</a> · <a href="/ultra_guides/en/manual/presets">Presets</a></td><td>Lorebook, regex, persona, presets</td></tr></tbody></table><p>In the app: Settings → <strong>Help &amp; feedback</strong> → <strong>User Manual</strong>.</p><h2 id="faq-short" tabindex="-1">FAQ (short) <a class="header-anchor" href="#faq-short" aria-label="Permalink to &quot;FAQ (short)&quot;">​</a></h2><p><strong>Q: What is MiniTavern Ultra?</strong><br> A: An AI roleplay chat app. Build a card in one sentence or import v2 / v3; chat with GPT, Claude, OpenRouter, or a local model. Keys and chats stay on the device first.</p><p><strong>Q: Is my data uploaded to your servers?</strong><br> A: Chats, characters, and keys stay on-device by default; model calls go to the third-party or local address <strong>you</strong> configure. See <a href="/ultra_guides/en/privacy">Privacy</a>.</p><p><strong>Q: Can I play without an API?</strong><br> A: You need a cloud Key, or follow <a href="/ultra_guides/en/local/">Run local models</a> to host on a PC then connect the phone. Common free quotas: <a href="/ultra_guides/en/free-cloud/">Free cloud APIs</a>; local image gen: <a href="/ultra_guides/en/local/image-gen/">Image model deploy</a>.</p><h2 id="download-and-policies" tabindex="-1">Download and policies <a class="header-anchor" href="#download-and-policies" aria-label="Permalink to &quot;Download and policies&quot;">​</a></h2><ul><li>Top bar <strong>Download MiniTavern</strong> · <a href="https://minitavern.github.io/ultra_website/" target="_blank" rel="noreferrer">Product site</a></li><li><a href="/ultra_guides/en/privacy">Privacy</a> · <a href="/ultra_guides/en/terms">Terms</a></li></ul>',22)])])}const f=r(l,[["render",i]]);export{m as __pageData,f as default};
